function acCards(){var pl=document.getElementById('pl-row');if(!pl)return;
 var w=document.getElementById('ac-row');
 if(!w){w=document.createElement('div');w.id='ac-row';w.className='ac-row';
  w.innerHTML='<div class="ac-w" id="ac-cap"></div><div class="ac-w" id="ac-reg"></div>';
  w.addEventListener('change',function(e){var t=e.target,k=acSemana();S.cb=S.cb||{};
   if(t.hasAttribute('data-accb')){var c=S.cb[k]||{};c.ok=t.checked;c.d=w.querySelector('[data-acd]').value;S.cb[k]=c;
    if(t.checked)try{anota('Captura da bandeira vencida: '+c.d,0,false);}catch(z){}grava();acPintaCards(true);try{vxRender();}catch(z){}}
   if(t.hasAttribute('data-acd')){var c2=S.cb[k]||{ok:false};c2.d=t.value;S.cb[k]=c2;grava();}
   if(t.hasAttribute('data-acta')){S.regras=t.value.split('\n').map(function(x){return x.trim();}).filter(Boolean);grava();acPintaCards(true);}});
  w.addEventListener('click',function(e){if(!e.target.hasAttribute('data-acre'))return;var ta=w.querySelector('[data-acta]'),ol=w.querySelector('.ac-rl');
   ta.hidden=!ta.hidden;ol.hidden=!ta.hidden;e.target.textContent=ta.hidden?'editar':'pronto';if(!ta.hidden)ta.focus();});}
 if(w.previousElementSibling!==pl&&!w.closest('#lat-ac'))pl.parentNode.insertBefore(w,pl.nextSibling);
 var ver=pl.offsetParent!==null;if(w.style.display!==(ver?'':'none'))w.style.display=ver?'':'none';acPintaCards(false);}
